// 每页最多16份本人原记录；未收到原死亡文书时只显示生前证面，不能据远方当前状态推死讯。
#include "private_shop_liquidation_view.hpp"
#include "private_shop_liquidation_detail.hpp"
#include "resident/domains/local_economy/economic_payload_guard.hpp"
namespace hanmo::resident {namespace {
using V=BoundaryValue;using A=V::Array;using D=V::Dict;using boundary::obj;constexpr Integer limit=16;
V identity(const WorldIdentity& s){StableId id;constexpr char hex[]="0123456789abcdef";for(auto b:s.world_id){id+=hex[b>>4];id+=hex[b&15];}return obj({{"world_id",V{id}},{"execution_epoch",V{s.execution_epoch}},{"revision",V{s.revision}},{"tick",V{s.tick}}});}
// 原命令和来源完整回显必须一致，拒把前世/另一人报价附在今天的控件。
Outcome<V> action(const PrivateShopLiquidationContext& x,const PrivateShopLiquidationPreview& preview,const StableId& actor,const PrivateShopLiquidationCommand& command,const StableId& label){
    if(!preview)return {false,{},common_failure("PrivateShopEstatePreviewUnavailable").error};auto q=preview(actor,command);if(!q.ok&&q.error.kind!=ErrorKind::rule)return {false,{},q.error};const auto kind=private_shop_liquidation_command_kind(command);auto params=encode_private_shop_liquidation_command(command);
    if(q.ok&&(!shop_liquidation_detail::same_identity(q.value.source_identity,x.common.state().identity)||q.value.actor_id!=actor||private_shop_liquidation_command_kind(q.value.command)!=kind||!compare_boundary(params,encode_private_shop_liquidation_command(q.value.command)).exact()))return {false,{},common_failure("PrivateShopEstatePreviewSourceMismatch").error};
    return {true,obj({{"command",V{kind}},{"params",std::move(params)},{"text",V{label}},{"available",V{q.ok}},{"code",V{q.ok?StableId{}:q.error.original.code}},{"quote",q.ok?encode_private_shop_liquidation_quote(q.value):V{}}}),{}};
}
V document(const PrivateShopExecutorMandate& m){return obj({{"mandate_fact_id",V{m.id}},{"acceptance_fact_id",V{m.acceptance_fact_id}},{"shop_id",V{m.shop_id}},{"proprietor_actor_id",V{m.proprietor_actor_id}},{"executor_actor_id",V{m.executor_actor_id}},{"appointed_tick",V{m.appointed_tick}},{"scope",V{StableId{"生前双方约定：收到原死亡文书后，只处理本店旧未交订单和归还剩余财货。"}}}});}
}
Outcome<PrivateShopLiquidationViewQuery> decode_private_shop_liquidation_query(const BoundaryValue& raw){auto unique=validate_economic_payload_fields(raw);if(!unique.ok)return {false,{},unique.error};try{using namespace boundary;fields(raw,{},{"tab","cursor","notice_binding_fact_id"},"private_shop_liquidations");PrivateShopLiquidationViewQuery q;if(raw.find("tab"))q.tab=get_string(raw,"tab","");if(raw.find("cursor"))q.cursor=get_int(raw,"cursor","");if(raw.find("notice_binding_fact_id"))q.notice_binding_fact_id=get_string(raw,"notice_binding_fact_id","");if(q.cursor<0||q.cursor>INT64_MAX-limit||q.notice_binding_fact_id.size()>256||(q.tab!="documents"&&q.tab!="meetings"&&q.tab!="estate")||(q.tab=="estate"&&q.notice_binding_fact_id.empty())||(q.tab!="estate"&&!q.notice_binding_fact_id.empty()))fail("PrivateShopEstateReadArguments","private_shop_liquidations");return {true,std::move(q),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<BoundaryValue> query_private_shop_liquidations(const PrivateShopLiquidationContext& x,const PrivateShopMeetingContext& meeting,const PrivateShopLiquidationPreview& preview,const PrivateShopLiquidationViewQuery& query,const PrivateShopEstateOrderPreview& orders){
    auto fail=[](const StableId& code)->Outcome<V>{return {false,{},common_failure(code).error};};const auto& c=x.common;const auto& actor=c.state().metadata.player_actor_id;if(!c.actor(actor)||query.cursor<0||query.cursor>INT64_MAX-limit||query.notice_binding_fact_id.size()>256||(query.tab!="estate"&&!query.notice_binding_fact_id.empty())||(query.tab=="estate"&&query.notice_binding_fact_id.empty())||(query.tab!="documents"&&query.tab!="meetings"&&query.tab!="estate"))return fail("PrivateShopEstateReadArguments");
    auto valid=validate_private_shop_liquidation_authorizations(x);if(!valid.ok)return {false,{},valid.error};A rows;Integer seen=0;bool more=false;auto take=[&](){const auto index=seen++;if(index<query.cursor)return false;if(index>=query.cursor+limit){more=true;return false;}return true;};
    if(query.tab=="documents"){
        // 不读对方撤约或当前生死；只有本人原决定与本人实际完成的清算可在证面旁展示。
        const auto& order=x.state.mandates.order();for(auto i=order.rbegin();i!=order.rend();++i){const auto& m=*x.state.mandates.find(*i);if(m.proprietor_actor_id!=actor&&m.executor_actor_id!=actor)continue;if(!take())continue;auto row=document(m);auto& fields=*row.as<D>();for(const auto& r:x.state.revocations.rows())if(r.second.mandate_fact_id==m.id&&r.second.actor_id==actor){fields.push_back({"own_decision",V{r.second.decision}});fields.push_back({"own_decision_fact_id",V{r.first}});}for(const auto& r:x.state.closings.rows())if(r.second.mandate_fact_id==m.id&&r.second.executor_actor_id==actor){fields.push_back({"own_closing_fact_id",V{r.first}});fields.push_back({"closed_tick",V{r.second.tick}});}rows.push_back(std::move(row));}
    }else if(query.tab=="meetings"){
        const InteractionSession* contact=nullptr;for(const auto& session:meeting.state.interactions)if(session.actor_id==actor)contact=&session;
        if(contact)for(const auto& policy:x.catalog.policies.rows()){
            const auto& p=policy.second;const bool proprietor=p.proprietor_actor_id==actor;const auto provider=proprietor?p.executor_actor_id:p.proprietor_actor_id;
            if((!proprietor&&p.executor_actor_id!=actor)||contact->phase!="say"||contact->context.provider_actor_id!=provider||contact->context.role_id!=(proprietor?p.executor_role_id:p.proprietor_role_id)||contact->dialogue_id!=(proprietor?p.executor_dialogue_id:p.proprietor_dialogue_id)||contact->node_id!=(proprietor?p.executor_acceptance_node_id:p.proprietor_appointment_node_id))continue;
            for(const auto& shop:x.shops.shops.rows())if(shop.second.terms.premises_id==p.premises_id&&shop.second.terms.proprietor_actor_id==p.proprietor_actor_id&&shop.second.status!="closed"&&take()){
                A actions;PrivateShopLiquidationCommand cmd=proprietor?PrivateShopLiquidationCommand{PrivateShopAppointExecutor{shop.first,p.id}}:PrivateShopLiquidationCommand{PrivateShopAcceptExecutorship{shop.first,p.id}};auto offered=action(x,preview,actor,cmd,proprietor?"指任对方为本店身后执行人":"本人接受这间店的身后委托");if(!offered.ok)return offered;actions.push_back(std::move(offered.value));
                for(const auto& m:x.state.mandates.rows())if(m.second.shop_id==shop.first&&m.second.policy_id==p.id&&!shop_liquidation_detail::revocation(x.state,m.first)){auto revoke=action(x,preview,actor,PrivateShopRevokeExecutor{m.first,proprietor?"revoke":"withdraw"},proprietor?"本人撤销该委托":"本人辞去该委托");if(!revoke.ok)return revoke;actions.push_back(std::move(revoke.value));}
                rows.push_back(obj({{"shop_id",V{shop.first}},{"policy_id",V{p.id}},{"proprietor_actor_id",V{p.proprietor_actor_id}},{"executor_actor_id",V{p.executor_actor_id}},{"actions",V{std::move(actions)}}}));
            }
        }
    }else {
        if(query.notice_binding_fact_id.empty()||!x.delivered_notice)return fail("PrivateShopEstateDeathNoticeNotReceived");auto notice=x.delivered_notice(actor,query.notice_binding_fact_id);if(!notice.ok)return {false,{},notice.error};if(!notice.value||notice.value->recipient_actor_id!=actor||notice.value->binding_fact_id!=query.notice_binding_fact_id||!shop_liquidation_detail::same_identity(notice.value->identity,c.state().identity)||notice.value->scenario_id!=c.state().metadata.scenario_id)return fail("PrivateShopEstateDeathNoticeNotReceived");
        for(const auto& m:x.state.mandates.rows())if(m.second.executor_actor_id==actor&&m.second.proprietor_actor_id==notice.value->decedent_actor_id){PrivateShopEstateClose command{m.second.shop_id,m.first,query.notice_binding_fact_id};auto authorized=read_private_shop_estate_closing_authority(x,actor,command);if(!authorized.ok){if(authorized.error.original.code=="PrivateShopEstateMandateRevoked"||authorized.error.original.code=="PrivateShopEstateAlreadyClosed")continue;return {false,{},authorized.error};}
            for(const auto& entry:x.shops.orders.orders.rows()){
                const auto& order=entry.second;if(order.terms.shop_id!=m.second.shop_id||order.status!="accepted")continue;bool complete=false;for(const auto& r:x.shops.order_settlements.rows())if(r.second.order_id==entry.first)complete=true;if(complete||!take())continue;
                if(!orders)return fail("PrivateShopEstateOrderPreviewUnavailable");TaskShopOrderEstateCancel cancel{m.second.shop_id,entry.first,m.first,query.notice_binding_fact_id};auto q=orders(actor,cancel);if(!q.ok&&q.error.kind!=ErrorKind::rule)return {false,{},q.error};if(q.ok&&(!shop_liquidation_detail::same_identity(q.value.source_identity,c.state().identity)||q.value.request.executor_actor_id!=actor||q.value.request.original_proprietor_actor_id!=m.second.proprietor_actor_id||q.value.request.shop_id!=cancel.shop_id||q.value.request.order_id!=cancel.order_id||q.value.request.mandate_fact_id!=cancel.mandate_fact_id||q.value.request.death_notice_binding_fact_id!=cancel.death_notice_binding_fact_id||q.value.task_id!=order.task_id))return fail("PrivateShopEstatePreviewSourceMismatch");
                auto row=document(m.second);auto& fields=*row.as<D>();fields.push_back({"order_id",V{entry.first}});fields.push_back({"task_id",V{order.task_id}});A actions;actions.push_back(obj({{"command",V{StableId{task_shop_order_estate_cancel_command}}},{"params",encode_task_shop_order_estate_command(cancel)},{"text",V{StableId{"取消本店这份未交订单并释放原客户预约"}}},{"available",V{q.ok}},{"code",V{q.ok?StableId{}:q.error.original.code}},{"quote",q.ok?obj({{"terms",encode_task_shop_order_estate_quote(q.value)}}):V{}}}));fields.push_back({"actions",V{std::move(actions)}});rows.push_back(std::move(row));
            }
            if(!take())continue;auto row=document(m.second);A actions;auto close=action(x,preview,actor,command,"清理已结责任并归还本店剩余财货");if(!close.ok)return close;actions.push_back(std::move(close.value));auto& fields=*row.as<D>();fields.push_back({"death_notice_binding_fact_id",V{query.notice_binding_fact_id}});fields.push_back({"actions",V{std::move(actions)}});rows.push_back(std::move(row));}
    }
    if(query.cursor>seen)return fail("PrivateShopEstateReadCursor");D page{{"ok",V{true}},{"source_identity",identity(c.state().identity)},{"observer_actor_id",V{actor}},{"tab",V{query.tab}},{"notice_binding_fact_id",V{query.notice_binding_fact_id}},{"rows",V{std::move(rows)}}};if(more)page.push_back({"next_cursor",V{query.cursor+limit}});return {true,V{std::move(page)},{}};
}
}
